<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';import { http } from '../api/http';
const data=ref<{roomUsage:Array<{name:string;count:number}>;statusDistribution:Array<{status:string;count:number}>}>({roomUsage:[],statusDistribution:[]});const maxRoom=computed(()=>Math.max(1,...data.value.roomUsage.map(x=>x.count)));const labels:Record<string,string>={PENDING:'待审批',APPROVED:'已批准',REJECTED:'已驳回',CHECKED_IN:'已签到',IN_PROGRESS:'进行中',COMPLETED:'已完成',CANCELLED:'已取消',NO_SHOW:'已失约'};const total=computed(()=>data.value.statusDistribution.reduce((n,x)=>n+x.count,0));onMounted(async()=>data.value=(await http.get('/statistics')).data);
</script>
<template><div class="page"><div class="page-header"><div><h2>统计分析</h2><p>洞察会议室使用情况和预约状态分布</p></div></div><div class="metric-grid"><div class="metric-card"><div class="label">累计预约</div><div class="value">{{total}}</div><small>所有状态记录</small></div><div class="metric-card"><div class="label">活跃会议室</div><div class="value">{{data.roomUsage.length}}</div><small>纳入统计资源</small></div><div class="metric-card"><div class="label">已完成</div><div class="value">{{data.statusDistribution.find(x=>x.status==='COMPLETED')?.count||0}}</div><small>正常结束会议</small></div><div class="metric-card"><div class="label">已取消</div><div class="value">{{data.statusDistribution.find(x=>x.status==='CANCELLED')?.count||0}}</div><small>释放资源记录</small></div></div><div class="two-column"><section class="panel"><div class="section-title"><h3>会议室使用排行</h3></div><div v-for="room in data.roomUsage" :key="room.name" class="bar-row"><span>{{room.name}}</span><div><i :style="{width:`${room.count/maxRoom*100}%`}"></i></div><b>{{room.count}} 次</b></div></section><section class="panel"><div class="section-title"><h3>预约状态分布</h3></div><div class="status-grid"><div v-for="item in data.statusDistribution" :key="item.status"><strong>{{item.count}}</strong><span>{{labels[item.status]||item.status}}</span><small>{{total?Math.round(item.count/total*100):0}}%</small></div></div></section></div></div></template>
<style scoped>.bar-row{display:grid;grid-template-columns:120px 1fr 55px;gap:14px;align-items:center;margin:22px 0;font-size:13px}.bar-row>div{height:9px;background:#edf1f6;border-radius:9px;overflow:hidden}.bar-row i{display:block;height:100%;background:linear-gradient(90deg,#3974e8,#63c9c0);border-radius:9px}.bar-row b{text-align:right;color:#3974e8}.status-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.status-grid>div{position:relative;padding:18px;border-radius:10px;background:#f6f8fb}.status-grid strong{display:block;font-size:24px}.status-grid span{font-size:12px;color:#7b8798}.status-grid small{position:absolute;right:14px;top:18px;color:#3974e8}</style>
